const raw = $input.item.json;
const startedAt = Date.now();
const rawFrom = String(raw.from || '');
const m = rawFrom.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
const address = (m ? m[2] : rawFrom).trim().toLowerCase();
const fromName = m ? m[1].trim() : '';
const fromDomain = address.includes('@') ? address.split('@').pop() : '';
const greetName = /^[A-Za-z][A-Za-z'-]+( |$)/.test(fromName) ? fromName.split(' ')[0] : 'there';
const subject = String(raw.subject || '').replace(/\s+/g, ' ').trim().slice(0, 200);
let body = String(raw.body || '').replace(/\r/g, '');
const injectionPatterns = [
  /ignore (all |any |the )?(previous|prior|above|earlier|your) (instructions|prompts?|rules|guidelines)/i,
  /disregard (all |any |the )?(previous|prior|above|your) (instructions|rules|guidelines)/i,
  /(reveal|print|show|disclose|repeat|output|display) (me )?(your |the )?(full |complete |entire |hidden )?(system|initial) ?(prompt|instructions|message)/i,
  /system (override|prompt|message)/i,
  /you are (now )?(no longer|now in|dan\b)/i,
  /(admin|developer|god|jailbreak) mode/i,
  /<\/?(instructions?|system|assistant|prompt|email)>/i,
  /(approve|process) (this|the|my) refund automatically/i,
  /(authori[sz]e|permit) you to (disclose|reveal|ignore|bypass)/i,
  /\bDAN\b/,
  /do not escalate/i,
  /knowledge base verbatim/i
];
const heuristicInjection = injectionPatterns.some((p) => p.test(subject + '\n' + body));
if (/<(html|body|div|p|br|table|span|a)[\s>\/]/i.test(body)) {
  body = body.replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n').replace(/<[^>]+>/g, ' ');
  body = body.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}
const cut = body.search(/^(On .{5,200} wrote:|-{2,} ?Original Message ?-{2,}|From: .+\nSent: )/m);
if (cut > 0) body = body.slice(0, cut);
const sig = body.indexOf('\n-- \n');
if (sig > 0) body = body.slice(0, sig);
body = body.split('\n').filter((l) => !l.startsWith('>')).join('\n').replace(/<\/?email>/gi, '[tag]').replace(/\n{3,}/g, '\n\n').replace(/[ \t]+/g, ' ').trim().slice(0, 4000);
const autoReply = /^(automatic reply|auto[- ]?reply|autoreply|out of office|delivery status|undeliverable|mail delivery)/i.test(subject) || /(no-?reply|noreply|donotreply|mailer-daemon|postmaster)/i.test(address);
return { json: { source: String(raw.source || 'unknown'), messageId: String(raw.messageId || ''), sampleId: String(raw.sampleId || ''), from: address, fromName, fromDomain, greetName, subject, body, emptyBody: body.length === 0, heuristicInjection, autoReply, startedAt } };

const base = $('Sanitize Email').item.json;
const j = $input.item.json;
let r = j.output !== undefined ? j.output : (j.text !== undefined ? j.text : j);
if (typeof r === 'string') {
  try { r = JSON.parse(r.replace(/```json|```/g, '').trim()); } catch (e) { r = null; }
}
const CATS = ['billing', 'bug_report', 'account_access', 'feature_request', 'sales_inquiry', 'how_to', 'spam', 'other'];
const PRIS = ['urgent', 'high', 'normal', 'low'];
const SENTS = ['positive', 'neutral', 'negative', 'angry'];
const ok = r && typeof r === 'object' && CATS.includes(r.category) && PRIS.includes(r.priority);
let c;
if (ok) {
  const conf = Math.min(1, Math.max(0, Number(r.confidence)));
  c = {
    category: r.category,
    priority: r.priority,
    sentiment: SENTS.includes(r.sentiment) ? r.sentiment : 'neutral',
    language: typeof r.language === 'string' && r.language.length <= 5 ? r.language.toLowerCase() : 'en',
    summary: String(r.summary || '').slice(0, 300),
    confidence: Number.isFinite(conf) ? conf : 0.5,
    modelNeedsHuman: r.needsHuman === true,
    modelReason: String(r.humanReason || '').slice(0, 200),
    injection: r.injectionSuspected === true,
    classificationStatus: 'ok'
  };
} else {
  c = { category: 'other', priority: 'normal', sentiment: 'neutral', language: 'en', summary: 'Automatic classification failed; please review manually.', confidence: 0, modelNeedsHuman: true, modelReason: 'Classifier output was invalid or unavailable', injection: false, classificationStatus: 'fallback' };
}
const injection = c.injection || base.heuristicInjection;
if (c.classificationStatus === 'fallback' && base.heuristicInjection) {
  // The model gave no usable answer, but the rule-based screen recognised an injection attempt: a real, safe result, not an outage.
  c = { ...c, priority: 'low', summary: 'Message appears to try to manipulate the assistant; flagged by the rule-based screen.', confidence: 0.6, modelReason: 'Rule-based injection screen (the model gave no usable answer)', classificationStatus: 'heuristic' };
}
const text = (base.subject + ' ' + base.body).toLowerCase();
const reasons = [];
if (c.modelNeedsHuman) reasons.push(c.modelReason || 'Model requested human review');
if (injection) reasons.push('Possible prompt injection');
// Rule-based net: nothing to read (empty body, or no letters at all) always goes to a person, whatever the model said.
if (base.emptyBody || !/\p{L}/u.test(base.body)) reasons.push('Empty or unintelligible message');
if (c.confidence < 0.7) reasons.push('Low confidence');
if (c.priority === 'urgent') reasons.push('Urgent priority');
if (c.sentiment === 'angry' && (c.priority === 'high' || c.priority === 'urgent')) reasons.push('Angry customer with high priority');
if (/\b(refund|chargeback|dispute|lawyer|legal action|gdpr|data protection|hack|compromis|stolen)/.test(text)) reasons.push('Sensitive topic (refund, legal, security or privacy)');
const skipReason = base.autoReply ? 'auto_reply' : (c.category === 'spam' ? 'spam' : (injection ? 'injection' : ''));
return { json: { ...base, category: c.category, priority: c.priority, sentiment: c.sentiment, language: c.language, summary: c.summary, confidence: c.confidence, needsHuman: reasons.length > 0, humanReason: Array.from(new Set(reasons)).join('; '), injectionSuspected: injection, skipReason, shouldDraft: skipReason === '', classificationStatus: c.classificationStatus } };

