const cls = $('Validate Classification').item.json;
const j = $input.item.json;
let r = j.output !== undefined ? j.output : (j.text !== undefined ? j.text : j);
if (typeof r === 'string') {
  try { r = JSON.parse(r.replace(/```json|```/g, '').trim()); } catch (e) { r = null; }
}
const problems = [];
const reply = (r && typeof r.reply === 'string' ? r.reply.trim() : '')
  .replace(/^([^\n]{1,60},)\n(?!\n)/, '$1\n\n')
  .replace(/([^\n])\n(Best regards,|Saludos cordiales,|Mit freundlichen Grüßen,|Cordialement,|Atenciosamente,)/, '$1\n\n$2');
if (!reply) problems.push(j.error ? 'draft model unavailable or rate-limited' : 'empty draft');
if (reply && reply.split(/\s+/).length > 220) problems.push('draft too long');
const urls = reply.match(/https?:\/\/[^\s)>"']+/gi) || [];
if (urls.some((u) => !/^https:\/\/(wrenbook\.example|status\.wrenbook\.example)(\/|$)/i.test(u.replace(/[.,;]+$/, '')))) problems.push('unapproved link');
const mails = reply.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
if (mails.some((a) => !/@wrenbook\.example$/i.test(a))) problems.push('unapproved email address');
const banned = [/refund (has been|was|is being|is approved|approved|processed|issued)/i, /(we|i)('ve| have| will|'ll) (refund|credit|compensate|waive)/i, /(we|i) guarantee/i, /(system prompt|knowledge base|kb-\d)/i, /<\/?email>/i];
if (banned.some((p) => p.test(reply))) problems.push('risky promise or prompt leak');
const kb = r && Array.isArray(r.kbArticlesUsed) ? r.kbArticlesUsed.map((x) => String(x)).slice(0, 5) : [];
const blocked = problems.length > 0;
const holdings = {
  en: ['Hi', 'Thanks for getting in touch. A teammate will review your message and follow up with you as soon as possible.', 'Best regards,'],
  es: ['Hola', 'Gracias por escribirnos. Un compañero revisará tu mensaje y te responderá lo antes posible.', 'Saludos cordiales,'],
  de: ['Hallo', 'Vielen Dank für Ihre Nachricht. Ein Teammitglied prüft Ihr Anliegen und meldet sich so bald wie möglich bei Ihnen.', 'Mit freundlichen Grüßen,'],
  fr: ['Bonjour', "Merci de nous avoir contactés. Un membre de l'équipe examinera votre message et vous répondra dès que possible.", 'Cordialement,'],
  pt: ['Olá', 'Obrigado por entrar em contato. Um membro da equipe analisará sua mensagem e responderá assim que possível.', 'Atenciosamente,']
};
const h = holdings[cls.language] || holdings.en;
const who = cls.greetName === 'there' ? '' : ' ' + cls.greetName;
const holding = h[0] + who + ',\n\n' + h[1] + '\n\n' + h[2] + '\nWrenbook Support';
const reasons = cls.humanReason ? [cls.humanReason] : [];
if (blocked) reasons.push('Draft failed safety checks: ' + problems.join(', '));
if (r && r.needsHuman === true) reasons.push('Draft assistant asked for human review');
const conf = r ? Math.min(1, Math.max(0, Number(r.confidence))) : 0;
return { json: { ...cls, needsHuman: reasons.length > 0, humanReason: reasons.join('; '), draftReply: blocked ? holding : reply, draftStatus: blocked ? 'holding_reply' : 'drafted', draftProblems: problems, kbArticlesUsed: kb, draftConfidence: Number.isFinite(conf) ? conf : 0 } };
